package setupui

const page = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Set up One Workspace</title><link rel="icon" type="image/svg+xml" href="/branding/icons/one_workspace.svg"><style>
:root{font-family:Inter,system-ui,sans-serif;color:#17233b;background:#f4f6fc}*{box-sizing:border-box}body{margin:0}main{max-width:1000px;margin:45px auto;background:white;border:1px solid #e2e7f2;border-radius:25px;overflow:hidden;box-shadow:0 20px 70px #2339760a}header{padding:28px 36px;border-bottom:1px solid #e8ecf5;display:flex;gap:14px;align-items:center}.logo{display:block;width:48px;height:48px;flex:none}.layout{display:grid;grid-template-columns:215px 1fr}aside{background:#f9faff;padding:34px 25px}aside p{color:#7a879e;padding:8px;border-radius:10px;font-size:14px}aside .active{background:#e8eeff;color:#345de5;font-weight:600}article{padding:30px 38px;min-height:530px}h1{font-size:29px;letter-spacing:-.7px;margin:0 0 10px}p{color:#69768d;line-height:1.65}label{display:block;font-size:14px;font-weight:600;margin:18px 0 7px}input,select{width:100%;padding:12px 14px;border:1px solid #ced6e7;border-radius:10px;background:white;color:#17233b;font:inherit}input:focus,select:focus{outline:2px solid #cfdaff;border-color:#345de5}.row{display:flex;gap:9px;align-items:center}.row input{min-width:0}.row button{padding:12px;font-size:14px}.split{display:grid;grid-template-columns:1fr 1fr;gap:15px}button{border:0;border-radius:10px;padding:13px 23px;font:inherit;cursor:pointer;color:white;background:#345de5}button.secondary{background:#eef2fa;color:#32405d}button:disabled{opacity:.45;cursor:wait}nav{display:flex;justify-content:space-between;margin-top:28px}.check{display:flex;align-items:flex-start;gap:10px;font-weight:400;line-height:1.5}.check input{width:18px;margin-top:3px}.note{background:#f1f5ff;padding:15px;border-radius:12px;font-size:14px}small{color:#69768d;display:block;line-height:1.5;margin-top:5px}.error{color:#a42636;background:#fff1f1;padding:14px;border-radius:12px;white-space:pre-wrap;overflow-wrap:anywhere}.progress{height:8px;border-radius:10px;background:#eaf0fc;overflow:hidden;margin:28px 0}.progress b{display:block;width:0;height:100%;background:#345de5;transition:width .3s}.checklist{list-style:none;padding:0;margin:20px 0}.checklist li{display:flex;gap:12px;padding:10px 0;border-bottom:1px solid #eef1f7}.stepmark{width:24px;height:24px;flex:none;border-radius:50%;display:grid;place-items:center;background:#edf1f8;color:#8590a3}.stepmark.done{background:#e0f3e7;color:#197345}.stepmark.running{background:#e4ebff;color:#345de5}.stepmark.warning{background:#fff0ce;color:#986600}.stepmark.failed{background:#ffe5e5;color:#a42636}.checklist strong{font-size:14px}.checklist small{overflow-wrap:anywhere}.progressmeta{font-size:13px;color:#69768d}.startup-note{font-size:14px;line-height:1.6}@keyframes slide{50%{transform:translateX(150%)}}[hidden]{display:none!important}a{color:#345de5}footer{padding:20px 36px;border-top:1px solid #edf0f6;font-size:12px;color:#7a879e}@media(max-width:720px){main{margin:12px}.layout{display:block}aside{display:none}article{padding:25px}.split{grid-template-columns:1fr}}
</style></head><body><main><header><img class="logo" src="/branding/icons/one_workspace.svg" alt="" width="48" height="48"><b>One Workspace</b><span style="margin-left:auto;color:#8490a5;font-size:13px" id="version">Setup</span></header><div class="layout"><aside><b>Make it yours</b><p id="step0" class="active">1 &nbsp; Your account</p><p id="step1">2 &nbsp; Apps & folders</p><p id="step2">3 &nbsp; Connection</p><p id="step3">4 &nbsp; Install</p></aside><article>
<section id="s0"><details class="note"><summary>Already have One Workspace? Update your installation</summary><p>Choose your existing Workspace parent folder. Your current accounts and files are retained.</p><label for="existingFolder">Existing Workspace folder</label><input id="existingFolder" placeholder="C:\Workspace"><button class="secondary" type="button" onclick="openExistingUpdates()" style="margin-top:14px">Open updates and recovery</button></details><h1>Your workspace starts here.</h1><p>One account for your Workspace apps. Setup downloads the latest published Workspace apps from GitHub.</p><label for="name">Your name</label><input id="name" autocomplete="name"><label for="email">Account email</label><input id="email" type="email" autocomplete="email"><small>This identifies your account. No email sending service is required.</small><div class="split"><div><label for="password">Password</label><input id="password" type="password" autocomplete="new-password" minlength="8" maxlength="128"></div><div><label for="confirm">Confirm password</label><input id="confirm" type="password" autocomplete="new-password"></div></div><small>Use at least 8 characters. Your administrator can reset passwords without email.</small></section>
<section id="s1" hidden><h1>One folder. Your workspace.</h1><p>Choose where Workspace will keep its apps, settings and files. Everything is organised for you inside this folder.</p><p class="note">Choose a folder on a local <b>NTFS drive</b>, usually C:. FAT and exFAT drives cannot protect your account data. We check your choice before you continue.</p><label for="folder">Workspace folder</label><div class="row"><input id="folder" placeholder="C:\Workspace" oninput="storageChanged()" onchange="validateStorage()" aria-describedby="storageHelp storageStatus"><button class="secondary" id="browseFolder" type="button" onclick="browse()">Browse</button></div><small id="storageHelp">Choose one parent folder. Workspace creates Apps, protected Private app folders, and ordinary Files underneath it.</small><p id="storageStatus" role="status" aria-live="polite" hidden></p><details style="margin-top:24px"><summary>Advanced: choose your apps</summary><p>All apps are selected by default. Uncheck apps you do not want. Your exclusions are remembered; new default apps are included automatically in future updates. Apps that need an unchecked app are also removed. MyAccounts is required for sign-in; Backups is built into Workspace. Docs uses the editor already embedded in Drive. Unchecking Docs removes its launcher entry.</p><div id="appChoices" role="group" aria-label="Apps to install"></div><small id="appCount"></small></details><label class="check"><input id="autostart" type="checkbox"> Start the suite when I sign in to Windows</label></section>
<section id="s2" hidden><h1>Bring your domain.</h1><p>Connect your domain and let Workspace set up the secure addresses, sign-in and Mail for you.</p><label for="mode">Where will you use Workspace?</label><select id="mode" onchange="connection()"><option value="automatic">Host on my domain — automatic setup</option><option value="local">Only on this computer</option><option value="manual">Advanced: existing HTTPS proxy</option><option value="cloudflare">Advanced: Cloudflare API token</option></select><div id="automatic"><label for="domain">Your domain</label><input id="domain" placeholder="example.com" autocomplete="off" oninput="domainChanged()"><small>Use a domain you manage in Cloudflare. You may also use a subdomain.</small><p><button type="button" id="connect" onclick="connectHosting()">Connect Cloudflare</button></p><p id="hostingPhase" role="status" aria-live="polite">Approve access to your domain in Cloudflare. Workspace discovers the settings for you.</p><div id="hostingAddresses" class="note" hidden></div><small>Installation creates a dedicated tunnel and new web addresses. Mail is prepared automatically; Internet email also needs a reachable mail server connection. Existing mail hosting is preserved.</small></div><div id="public" hidden><label>Workspace address</label><input id="origin" placeholder="https://workspace.example.com"><label>MyAccounts address</label><input id="issuer" placeholder="https://login.example.com"></div><div id="cloudflare" hidden><label>Account ID</label><input id="accountId"><label>Zone ID</label><input id="zoneId"><label>Scoped Cloudflare API token</label><input id="cfToken" type="password" autocomplete="off"><small>Needs Account Cloudflare Tunnel:Edit, Zone DNS:Edit and Zone:Read. Credentials needed for automatic mail DNS and TLS renewal are encrypted on this computer.</small><label class="check"><input id="authorize" type="checkbox"> Create a dedicated tunnel and new DNS records.</label></div><details style="margin-top:24px"><summary>Advanced options</summary><label>Base port</label><input id="port" type="number" min="1024" max="65530" value="8990"><small>Internal app ports are assigned automatically from this port.</small></details></section>
<section id="s3" hidden><h1 id="installTitle">Ready for your workspace.</h1><p id="summary">Setup will verify the bundled apps, create your owner account and connect the suite. Current versions of Drive, Docs and Photos are evaluation builds.</p><div class="progress" id="progress" role="progressbar" aria-label="Completed setup steps" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0" hidden><b id="progressFill"></b></div><p id="progressMeta" class="progressmeta" aria-live="polite"></p><p id="phase" role="status" aria-live="polite"></p><ul id="checklist" class="checklist"></ul><div id="complete" hidden><p class="note" id="startupNote">Your apps are installed. Start Workspace to check the secure connection and bring each app online.</p><button onclick="launch()" id="launch">Launch Workspace</button><p><a id="workspaceLink" target="_blank" rel="noopener" hidden>Open Workspace →</a></p><small>You can close this setup window after launch. Double-click Workspace.exe in your program folder to start the suite again.</small></div></section>
<p id="error" class="error" hidden></p><nav id="navigation"><button class="secondary" onclick="show(step-1)" id="back" disabled>Back</button><button onclick="next()" id="next">Continue →</button></nav></article></div><footer>Self-hosted · Automatic domain setup · Your files stay on your chosen drive</footer></main>
<script>
let step=0,busy=false,installed=false,hosting=null,connecting=false,pollTimer;const initialScreen=new URLSearchParams(location.search).get('screen'),token=location.hash.slice(1);history.replaceState(null,'',location.pathname);const $=id=>document.getElementById(id);
async function api(path,body){let r=await fetch('/api/'+path,{method:body===undefined?'GET':'POST',headers:{'X-Setup-Token':token,'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});if(!r.ok)throw Error(await r.text());return r.status===202||r.status===204?{}:r.json()}
function error(e){$('error').textContent=e.message||e;$('error').hidden=false}
function show(n){if(n<0||n>3||busy)return;step=n;for(let i=0;i<4;i++){$('s'+i).hidden=i!==n;$('step'+i).className=i===n?'active':''}$('back').disabled=n===0;$('next').textContent=n===3?'Install Workspace':'Continue →';$('error').hidden=true}
function request(){let v={};for(let k of ['folder','name','email','password','confirm','mode','origin','issuer','cfToken','accountId','zoneId','domain'])v[k]=$(k).value.trim();if(v.mode!=='automatic')v.domain='';v.password=$('password').value;v.confirm=$('confirm').value;v.port=+$('port').value;for(let k of ['autostart','authorize'])v[k]=$(k).checked;if(appCatalog.length)v.selectedApps=appCatalog.filter(a=>appChecks[a.id].checked).map(a=>a.id);v.photos=!!appChecks.photos?.checked;return v}
async function next(){if(step<3){if(step===0&&(!$('name').value||!$('email').validity.valid||!$('email').value||$('password').value.length<8||$('password').value.length>128||$('password').value!==$('confirm').value)){error('Enter your name, valid email and matching passwords of 8 to 128 characters.');return}if(step===1&&!appCatalog.length){error('The app list has not loaded. Refresh setup before continuing.');return}if(step===1&&!(await validateStorage()))return;if(step===2&&$('mode').value==='automatic'&&(!hosting||connecting||hosting.domain!==normalDomain())){error('Enter your domain and connect Cloudflare to continue.');return}if(step===2){const names=appCatalog.filter(a=>appChecks[a.id].checked).map(a=>a.name).join(', ');$('summary').textContent=($('mode').value==='automatic'&&hosting?'Workspace will create '+hosting.origin+' and '+hosting.issuer+'. Your existing DNS records are preserved. ':'Setup will connect your selected apps. ')+'Installing: '+names+'. Backups is included, with scheduling off.';}show(step+1);return}try{await api('install',request());busy=true;$('next').disabled=true;$('back').disabled=true;$('progress').hidden=false;$('error').hidden=true;for(let k of ['password','confirm','cfToken'])$(k).value='';poll()}catch(e){error(e)}}
let storageSequence=0;
function storageChanged(){storageSequence++;$('storageStatus').hidden=true;$('folder').removeAttribute('aria-invalid')}
async function validateStorage(){const sequence=++storageSequence,folder=$('folder').value.trim(),message=$('storageStatus');message.hidden=false;message.className='muted';message.textContent='Checking this folder…';try{if(!folder)throw Error('Choose your Workspace folder.');const result=await api('storage',{folder});if(sequence!==storageSequence||folder!==$('folder').value.trim())return false;message.className='note';message.textContent='Ready: '+result.volume.root+' supports protected account data. Workspace will organise everything inside your selected folder.';$('folder').removeAttribute('aria-invalid');return true}catch(e){if(sequence!==storageSequence)return false;message.className='error';message.textContent=e.message||e;$('folder').setAttribute('aria-invalid','true');return false}}
async function openExistingUpdates(){try{await api('updates/open',{folder:$('existingFolder').value.trim()});error('Update window opened on this PC. Continue there.')}catch(e){error(e)}}
async function browse(){const b=$('browseFolder');b.disabled=true;b.textContent='Choose a folder…';$('next').disabled=true;try{const r=await api('browse',{folder:$('folder').value.trim()});if(r.path){$('folder').value=r.path;await validateStorage()}}catch(e){if(!String(e.message).includes('Folder selection cancelled'))error(e)}finally{b.disabled=false;b.textContent='Browse';$('next').disabled=false;$('folder').focus()}}
function normalDomain(){return $('domain').value.trim().toLowerCase().replace(/\.$/,'')}
function domainChanged(){if(hosting&&hosting.domain!==normalDomain()){hosting=null;$('hostingAddresses').hidden=true;$('hostingPhase').textContent='Connect Cloudflare for this domain to continue.'}}
function connection(){const mode=$('mode').value;$('automatic').hidden=mode!=='automatic';$('public').hidden=mode!=='manual'&&mode!=='cloudflare';$('cloudflare').hidden=mode!=='cloudflare'}
async function connectHosting(){try{await api('hosting/connect',{domain:normalDomain()});connecting=true;hosting=null;$('connect').disabled=true;$('hostingAddresses').hidden=true;$('error').hidden=true;pollHosting()}catch(e){error(e)}}
function hostingState(r){connecting=!!r.connecting;$('connect').disabled=connecting;$('hostingPhase').textContent=r.hostingError||r.hostingPhase||$('hostingPhase').textContent;if(r.hosting){hosting=r.hosting;$('hostingAddresses').textContent='Workspace: '+hosting.origin+' · Accounts: '+hosting.issuer;$('hostingAddresses').hidden=hosting.domain!==normalDomain()}}
async function pollHosting(){try{const r=await api('state');hostingState(r);if(r.connecting)setTimeout(pollHosting,1000)}catch(e){connecting=false;$('connect').disabled=false;error(e)}}
function drawProgress(p){if(!p)return;$('progress').hidden=false;$('progressFill').style.width=p.percent+'%';$('progress').setAttribute('aria-valuenow',String(p.percent));const elapsed=Math.max(0,Math.floor((Date.now()-Date.parse(p.startedAt))/1000));$('progressMeta').textContent=p.completed+' of '+p.total+' steps complete'+(['starting','installing'].includes(p.state)?' · '+Math.floor(elapsed/60)+'m '+elapsed%60+'s elapsed':'');$('phase').textContent=p.phase;const list=$('checklist');list.replaceChildren();for(const item of p.steps){const row=document.createElement('li'),mark=document.createElement('span'),text=document.createElement('div'),title=document.createElement('strong');mark.className='stepmark '+item.state;mark.textContent=({done:'✓',running:'…',warning:'!',failed:'×'})[item.state]||'·';title.textContent=item.label;text.append(title);if(item.detail){const detail=document.createElement('small');detail.textContent=item.detail;text.append(detail)}row.append(mark,text);list.append(row)}}
let appCatalog=[],appChecks={};
function appChoices(apps){if(appCatalog.length||!apps?.length)return;appCatalog=apps;for(const app of apps){const label=document.createElement('label'),check=document.createElement('input'),text=document.createElement('span');label.className='check';check.type='checkbox';check.checked=true;check.disabled=app.id==='accounts';appChecks[app.id]=check;text.textContent=app.name+(app.id==='accounts'?' (required)':'');const hint=document.createElement('small');hint.textContent=app.description;text.append(hint);label.append(check,text);$('appChoices').append(label);check.onchange=()=>{if(check.checked){const include=id=>{for(const dep of appCatalog.find(a=>a.id===id)?.depends||[]){appChecks[dep].checked=true;include(dep)}};include(app.id)}else{let changed=true;while(changed){changed=false;for(const a of appCatalog){if(appChecks[a.id].checked&&(a.depends||[]).some(dep=>!appChecks[dep].checked)){appChecks[a.id].checked=false;changed=true}}}}appCount()}}appCount()}
function appCount(){$('appCount').textContent=appCatalog.filter(a=>appChecks[a.id].checked).length+' of '+appCatalog.length+' apps selected. Backups is included and scheduling starts off.'}
async function poll(){clearTimeout(pollTimer);try{const r=await api('state');appChoices(r.availableApps);$('version').textContent=r.offline?'Offline bundle '+r.version:installed?r.version:'Latest apps from GitHub';hostingState(r);if(r.ready){busy=false;installed=true;if(step!==3)show(3);$('navigation').hidden=true;$('complete').hidden=false;$('summary').textContent='Your apps are installed. Follow startup below to see what is running and what remains.';$('workspaceLink').href=r.origin;const p=r.startup;drawProgress(p||r.installation);const failed=(p?.state==='failed'?p.error:'')||r.launchError;if(failed){$('installTitle').textContent='Startup needs attention.';$('startupNote').textContent='Workspace stopped before it was ready. The failed step and remaining steps are shown below.';$('launch').disabled=false;$('launch').textContent='Retry startup';$('workspaceLink').hidden=true;error(failed+(r.logPath?'\nStartup log: '+r.logPath:''))}else if(p?.state==='ready'){$('installTitle').textContent='Your Workspace is running.';$('startupNote').textContent=p.steps.some(x=>x.state==='warning')?'Workspace is ready. Review the items marked for attention.':'All startup checks passed. You can open Workspace now.';$('launch').disabled=true;$('launch').textContent='Workspace is running';$('workspaceLink').hidden=false;$('error').hidden=true}else if(r.launching||p?.state==='starting'){$('installTitle').textContent='Starting your Workspace…';$('startupNote').textContent='Keep this page open for live progress. Completed steps, the current task and remaining tasks are shown below.';$('launch').disabled=true;$('launch').textContent='Workspace is starting…';$('workspaceLink').hidden=true;$('error').hidden=true;if(!p)$('phase').textContent='Starting the Workspace launcher…'}else{$('installTitle').textContent='Your apps are installed.';$('launch').disabled=false;$('launch').textContent=p?.state==='stopped'?'Start Workspace again':'Launch Workspace';$('workspaceLink').hidden=true}pollTimer=setTimeout(poll,p?.state==='ready'?4000:1000);return}drawProgress(r.installation);$('phase').textContent=r.phase;if(r.error){busy=false;error(r.error);$('back').disabled=false;$('next').disabled=false;return}if(r.busy)pollTimer=setTimeout(poll,1000)}catch(e){error(e);if(installed||busy)pollTimer=setTimeout(poll,2000)}}
async function launch(){const b=$('launch');b.disabled=true;b.textContent='Starting…';$('error').hidden=true;try{await api('launch',{});poll()}catch(e){b.disabled=false;b.textContent='Retry startup';error(e)}}
connection();if(initialScreen==='hosting')show(2);if(initialScreen==='storage')show(1);poll();
</script></body></html>`
